assert.equal(sha('../g4-challenge-retry-package-20261022/src/network/challenge-replica-host.mjs'),inputs['network/challenge-replica-host.mjs']);
const ri=read('../g4-config-independent-review-20261021/revision2/root-txt-runner/artifacts/host-services-runner.mjs.inputs.json');
for(const f of ['network/host-services/roles.mjs','network/host-services/runner.mjs','network/host-services/service-tls.mjs'])assert.equal(sha('../g4-config-independent-review-20261021/revision2/hs2-tree/'+f),ri[f]);
const cr=challengeReplicaConfig(read('config/challengeReplica.parallel-txt.draft.json'));
const hs=validateHostServicesConfig(read('config/host-services.parallel-txt.draft.json'));
const rd=hs.services.find(x=>x.role==='route-dns'),tls=hs.services.find(x=>x.role==='service-tls');
assert.equal(tls.config.challenge.declarationFile,cr.front.declarationFile);
assert.equal(cr.front.declarationFile,'C:\\ProgramData\\Enclave\\challenge-replica\\challenge-front.json');
assert.equal(tls.config.challenge.frontPort,cr.front.listen.port);
assert.deepEqual(tls.config.challenge.release,{dnsSha256:cr.release.dnsSha256,runtimeBundleSha256:cr.release.runtimeBundleSha256});
