const p=resolveHostPolicyConfig({env:hostPolicyGateEnv(cr.hostPolicy).env,chainId:8453}).config;
const production=resolveHostPolicyConfig({env:{ENCLAVE_PLATFORM_HOST_POLICY:'production'},chainId:8453}).config;
