const result={at:new Date().toISOString(),pass:true,exactCandidateValidators:true,sharedDeclarationPath:cr.front.declarationFile,orders:'held',adminControlsUnchanged:true,shieldOnly:!cr.snp,liveActivation:false};
fs.writeFileSync(new URL('config-verdict.json',base),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
